/* eslint-disable no-undef */
function normalizePart(value) {
  return String(value || '')
    .replace(/\\/g, '/')
    .replace(/^\/+/, '')
    .replace(/\/+$/, '')
}

export function buildPublicAssetPath(...segments) {
  const normalized = segments
    .map((segment) => normalizePart(segment))
    .filter((segment) => segment.length > 0)
    .join('/')

  // Use __webpack_public_path__ at runtime (set by vue.config.js publicPath)
  // Falls back to relative path './' for GitHub Pages deployment
  let base = typeof __webpack_public_path__ !== 'undefined' 
    ? __webpack_public_path__ 
    : './'
  
  // Normalize base path
  base = String(base || './').replace(/\\/g, '/').replace(/\/\/+$/, '')
  if (base === '') base = './'

  if (normalized.length === 0) return base
  if (base === '/' || base === './') {
    return base === './' ? `./${normalized}` : `/${normalized}`
  }
  
  // Handle relative base paths (like './')
  if (base.startsWith('.')) {
    return `${base}/${normalized}`
  }
  
  // Handle absolute paths
  if (!base.startsWith('/')) {
    base = '/' + base
  }
  
  return `${base}/${normalized}`
}
/* eslint-enable no-undef */
